                    #include "guard.h"


BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.mram.name}_open_guard (flash_ctrl_t *const p_api_ctrl, flash_cfg_t const *const p_cfg)
{
    /* TODO: add your own security checks here */

    FSP_PARAMETER_NOT_USED(p_api_ctrl);
    FSP_PARAMETER_NOT_USED(p_cfg);

    return R_MRAM_Open(&${module.driver.mram.name}_ctrl, &${module.driver.mram.name}_cfg);
}

BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.mram.name}_write_guard (flash_ctrl_t *const p_api_ctrl, uint32_t const src_address, uint32_t flash_address, uint32_t const num_bytes)
{
    /* TODO: add your own security checks here */

    FSP_PARAMETER_NOT_USED(p_api_ctrl);

    FSP_ERROR_RETURN(num_bytes != 0U, FSP_ERR_INVALID_SIZE);
    FSP_ERROR_RETURN(cmse_check_address_range((void *)(uintptr_t) src_address, num_bytes, CMSE_NONSECURE | CMSE_MPU_READ) != NULL, FSP_ERR_INVALID_ADDRESS);
    return R_MRAM_Write(&${module.driver.mram.name}_ctrl, src_address, flash_address, num_bytes);
}

BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.mram.name}_erase_guard (flash_ctrl_t *const p_api_ctrl, uint32_t const address, uint32_t const num_blocks)
{
    /* TODO: add your own security checks here */

    FSP_PARAMETER_NOT_USED(p_api_ctrl);

    return R_MRAM_Erase(&${module.driver.mram.name}_ctrl, address, num_blocks);
}

BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.mram.name}_blank_check_guard (flash_ctrl_t *const p_api_ctrl, uint32_t const address, uint32_t num_bytes, flash_result_t *p_blank_check_result)
{
    /* Verify all pointers are in non-secure memory. */
    flash_result_t * p_blank_check_result_checked = cmse_check_pointed_object(p_blank_check_result, CMSE_AU_NONSECURE);
    FSP_ASSERT(p_blank_check_result_checked != NULL);

    /* TODO: add your own security checks here */

    FSP_PARAMETER_NOT_USED(p_api_ctrl);

    return R_MRAM_BlankCheck(&${module.driver.mram.name}_ctrl, address, num_bytes, p_blank_check_result_checked);
}

BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.mram.name}_close_guard (flash_ctrl_t *const p_api_ctrl)
{
    /* TODO: add your own security checks here */

    FSP_PARAMETER_NOT_USED(p_api_ctrl);

    return R_MRAM_Close(&${module.driver.mram.name}_ctrl);
}

