BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.mram.name}_callback_set_guard (flash_ctrl_t *const p_api_ctrl, void(*p_callback)(flash_callback_args_t *), void const *const p_context, flash_callback_args_t *const p_callback_memory)
{
    /* Verify all pointers are in non-secure memory. */
    void(*p_callback_checked)(flash_callback_args_t *) = (void(*)(flash_callback_args_t *)) cmse_check_address_range((void *) p_callback, sizeof(void *), CMSE_AU_NONSECURE);
    FSP_ERROR_RETURN(p_callback_checked != NULL, FSP_ERR_INVALID_ADDRESS);
    flash_callback_args_t *const p_callback_memory_checked = cmse_check_pointed_object(p_callback_memory, CMSE_AU_NONSECURE | CMSE_MPU_READWRITE);
    FSP_ERROR_RETURN(p_callback_memory_checked != NULL, FSP_ERR_NO_CALLBACK_MEMORY);

    /* TODO: add your own security checks here */

    FSP_PARAMETER_NOT_USED(p_api_ctrl);
    FSP_PARAMETER_NOT_USED(p_context);

    return R_MRAM_CallbackSet(&${module.driver.mram.name}_ctrl, p_callback_checked, p_context, p_callback_memory_checked);
}

